import { actor } from "rivetkit";
import { db, integer, sqliteTable, text } from "rivetkit/db/drizzle";
import migrations from "./drizzle/migrations";

// The same schema you used with drizzle-orm/d1
export const users = sqliteTable("users", {
	id: integer("id").primaryKey({ autoIncrement: true }),
	email: text("email").notNull().unique(),
	name: text("name").notNull(),
});

export const tenantDb = actor({
	// Applies the migrations generated by drizzle-kit
	db: db({ schema: { users }, migrations }),
	actions: {
		getUser: async (c, id: number) => {
			const user = await c.db.query.users.findFirst({
				where: (users, { eq }) => eq(users.id, id),
			});
			return user ?? null;
		},
	},
});
